mod_intentions_ui <- function(id) uiOutput(NS(id)("form"))
mod_intentions_server <- function(id,con,user,on_saved) moduleServer(id,function(input,output,session){
  revision<-reactiveVal(0L)
  output$form<-renderUI({req(user());revision();x<-member_context(con,user());ns<-session$ns
    panel("Intentions & everyday compatibility",tags$p("Choose what you want to share. An essential requirement excludes profiles without a matching answer, including unanswered profiles. Strong and nice-to-have preferences guide ranking only in Love."),
      selectInput(ns("availability"),"Right now I am…",c("Actively connecting"="active","Open to conversations"="open","Taking a break from discovery"="paused"),x$availability),
      checkboxGroupInput(ns("intentions"),"My relationship intentions (choose any that fit)",INTENTIONS,x$intentions),
      tags$div(class="context-grid",lapply(names(CONTEXT_FIELDS),function(key){p<-x$preferences[[key]]%||%list();tags$details(class="context-preference",tags$summary(switch(key,children="Future children",existing_children="Existing children",structure="Relationship structure",relocation="Relocation",alcohol="Alcohol",pets="Pets")),selectInput(ns(paste0("own_",key)),"My answer (optional)",c("Keep private / unanswered"="",CONTEXT_FIELDS[[key]]),x$attributes[[key]]%||%""),checkboxGroupInput(ns(paste0("want_",key)),"In a partner (none selected = any)",CONTEXT_FIELDS[[key]],unlist(p$values)),selectInput(ns(paste0("importance_",key)),"How important is this?",c("Nice to have"="nice","Strong preference"="strong","Essential requirement"="essential"),p$importance%||%"nice"))})),
      checkboxGroupInput(ns("want_intentions"),"Preferred partner intentions (none = any)",INTENTIONS,unlist(x$preferences$intentions$values)),selectInput(ns("importance_intentions"),"Importance of partner intentions",c("Nice to have"="nice","Strong preference"="strong","Essential requirement"="essential"),x$preferences$intentions$importance%||%"nice"),
      tags$details(tags$summary("Optional location, faith and cultural context"),tags$p(class="fine-print","Region means a place you enter, not a calculated distance. No location is inferred. These optional text preferences use an exact text match."),lapply(c("region","faith","culture"),function(key)tagList(textInput(ns(paste0("own_",key)),paste("My",key,"(optional)"),x$attributes[[key]]%||%""),textInput(ns(paste0("want_",key)),paste("Preferred",key,"(optional)"),paste(unlist(x$preferences[[key]]$values),collapse="")),selectInput(ns(paste0("importance_",key)),"Importance",c("Nice to have"="nice","Strong preference"="strong","Essential requirement"="essential"),x$preferences[[key]]$importance%||%"nice")))),
      tags$h3("Beyond the photo"),tags$p("These optional words become part of your public member profile. Questionnaire answers stay private."),lapply(names(BEYOND_PROMPTS),function(key)textAreaInput(ns(paste0("beyond_",key)),BEYOND_PROMPTS[[key]],x$beyond[[key]]%||%"",rows=2)),actionButton(ns("save"),"Save my intentions & story",class="btn-primary"))
  })
  observeEvent(input$save,tryCatch({
    req(user());x<-list(availability=input$availability,intentions=input$intentions%||%character(),attributes=list(),preferences=list(),beyond=list())
    for(key in c(names(CONTEXT_FIELDS),"region","faith","culture")){x$attributes[[key]]<-input[[paste0("own_",key)]]%||%"";values<-input[[paste0("want_",key)]]%||%character();values<-values[nzchar(values)];x$preferences[[key]]<-list(values=as.list(values),importance=input[[paste0("importance_",key)]]%||%"nice")}
    x$preferences$intentions<-list(values=as.list(input$want_intentions%||%character()),importance=input$importance_intentions)
    x$beyond<-setNames(lapply(names(BEYOND_PROMPTS),function(k)input[[paste0("beyond_",k)]]%||%""),names(BEYOND_PROMPTS))
    save_member_context(con,user(),x);on_saved();showNotification("Your intentions and story are saved.",type="message")
  },error=function(e)showNotification(conditionMessage(e),type="error")))
  observeEvent(user(),revision(isolate(revision())+1L),ignoreNULL=FALSE)
})
mod_insights_ui <- function(id) tagList(selectInput(NS(id)("mode"),"Explore my pool",c("Love"="love","Friends"="friends")),uiOutput(NS(id)("summary")))
mod_insights_server <- function(id,con,user,registry,revision) moduleServer(id,function(input,output,session){
  output$summary<-renderUI({req(user());revision();p<-get_profile(con,user());req(!is.null(p));mode<-input$mode%||%"love"
    if(!mode%in%p$connection_modes)return(empty_state("This space is paused.","Enable it in My profile when you feel ready."))
    x<-dating_insights(con,user(),registry,mode)
    count<-function(label,n)tags$div(class="insight-stat",tags$b(n),tags$span(label))
    tagList(tags$div(class="insights-grid",count("Active, opted-in members before mutual preferences",x$active_pool),count("Meet both people's essential requirements",x$eligible_pool),count("Also close to your soft profile preferences",x$close_to_soft)),
      panel("Preferences are a compass",tags$p(paste(x$outside_soft,"eligible members fall outside some of your soft preferences. They may still be worth a thoughtful introduction.")),tags$p("These are counts in the current SoulMatch community, not estimates of anyone's attraction to you. A small pool can reflect community size and other people's choices as well as your own."),tags$p("Essential requirements stay in place. Flexible preferences guide ranking without excluding someone. You do not need to change a boundary to use SoulMatch."),tags$p(class="fine-print","This snapshot excludes blocked, suspended, incomplete and paused profiles. It does not provide names or private details of people outside your pool. No geographic-distance estimate is available yet.")))
  })
})
mod_post_date_ui<-function(id)tagList(actionButton(NS(id)("refresh_feedback"),"Refresh meeting status",class="btn-outline-primary"),uiOutput(NS(id)("form")),uiOutput(NS(id)("questions")))
mod_post_date_server<-function(id,con,user,revision,on_saved)moduleServer(id,function(input,output,session){
  choices<-reactive({req(user());revision();r<-DBI::dbGetQuery(con,"SELECT target_id,mode FROM decisions WHERE actor_id=? AND decision='like'",params=list(user()));x<-character();for(i in seq_len(nrow(r)))if(is_mutual(con,user(),r$target_id[i],r$mode[i]))x[paste(get_profile(con,r$target_id[i])$name,if(r$mode[i]=="love")"Love" else "Friends",sep=" · ")]<-paste(r$mode[i],r$target_id[i],sep=":");x})
  selected<-reactive({req(input$person);assert(input$person%in%unname(choices()),"Choose an active mutual connection.");p<-strsplit(input$person,":",fixed=TRUE)[[1]];list(mode=p[1],target=p[2])})
  output$form<-renderUI({x<-choices();if(!length(x))return(empty_state("A real-world chapter, when you're ready.","Optional meeting feedback becomes available for mutual connections."));ns<-session$ns;selectInput(ns("person"),"Connection",x,isolate(input$person)%||%x[[1]])})
  output$questions<-renderUI({req(user());revision();s<-selected();ns<-session$ns
    if(!both_met(con,user(),s$target,s$mode))return(panel("Have you met?",tags$p("Confirm only if you actually met. Each person confirms independently. The optional feedback form opens after both confirmations."),actionButton(ns("confirm"),"We met in person",class="btn-outline-primary")))
    row<-DBI::dbGetQuery(con,"SELECT * FROM post_date_feedback WHERE user_id=? AND target_id=? AND mode=?",params=list(user(),s$target,s$mode));saved<-if(nrow(row))as.list(row[1,]) else list()
    scale<-function(key,label)selectInput(ns(key),label,optional_choices(c("1 · Not at all","2","3","4","5 · Very much")),saved[[key]]%||%"")
    yesno<-function(key,label)selectInput(ns(key),label,c("Leave unanswered"="","Yes"="yes","No"="no","Unsure"="unsure"),saved[[key]]%||%"")
    panel("A private reflection after meeting",tags$p("Optional. Your connection never sees your answers. You can return to update your own feedback. For Friends, attraction and second-date questions can be left unanswered."),scale("comfort","How comfortable did you feel?"),scale("attraction","Did you experience romantic attraction?"),scale("naturalness","How natural did the conversation feel?"),yesno("second_date","Would you like to meet this person again?"),scale("profile_accuracy","How well did the profile reflect your experience?"),yesno("relationship_formed","Has a relationship formed? (optional follow-up)"),scale("satisfaction","If applicable, how satisfied do you feel with the relationship?"),yesno("safe_respected","Did you feel safe and respected? Stored separately from matching research."),tags$p(class="fine-print","This questionnaire is not a safety-reporting channel. Use Report & block in Messages to send a concern to the local operator."),checkboxInput(ns("consent"),"Allow these non-safety outcomes to contribute to matching research, subject to my current profile research consent",isTRUE(as.logical(saved$research_consent%||%FALSE))),actionButton(ns("save"),"Save private feedback",class="btn-primary"))
  })
  outputOptions(output,"questions",suspendWhenHidden=FALSE)
  observeEvent(input$refresh_feedback,on_saved())
  observeEvent(input$confirm,tryCatch({s<-selected();confirm_meeting(con,user(),s$target,s$mode);on_saved()},error=function(e)showNotification(conditionMessage(e),type="error")))
  observeEvent(input$save,tryCatch({s<-selected();f<-setNames(lapply(c("comfort","attraction","naturalness","second_date","profile_accuracy","relationship_formed","satisfaction","safe_respected"),function(k)input[[k]]%||%""),c("comfort","attraction","naturalness","second_date","profile_accuracy","relationship_formed","satisfaction","safe_respected"));f$research_consent<-isTRUE(input$consent);save_post_date(con,user(),s$target,s$mode,f);on_saved();showNotification("Your private feedback is saved.",type="message")},error=function(e)showNotification(conditionMessage(e),type="error")))
})
mod_admin_ui<-function(id){ns<-NS(id);tagList(uiOutput(ns("gate")))}
mod_admin_server<-function(id,con,user,registry,algorithms,revision,on_saved)moduleServer(id,function(input,output,session){
  report<-eventReactive(input$refresh,{req(user());require_admin(con,user());admin_research_summary(con,user(),registry,as.integer(input$days%||%30))},ignoreNULL=FALSE)
  output$gate<-renderUI({req(user());revision();if(!is_admin(con,user()))return(empty_state("A private research workspace.","Administrator access is assigned by the database operator, never by registration or a profile setting."));ns<-session$ns
    tagList(panel("Matching Research & Evaluation",tags$p("Live counts exclude fictional demo members. These operational measurements do not establish predictive validity, causation, chemistry, or relationship quality."),selectInput(ns("days"),"Observation window",c("7 days"=7,"30 days"=30,"90 days"=90),30),actionButton(ns("refresh"),"Refresh research view",class="btn-primary"),tableOutput(ns("metrics")),tags$h4("Recorded offline evaluations"),tableOutput(ns("models")),tags$p(class="fine-print","Empty means no evaluation was recorded. Use --record-db with the offline training script. Held-out metrics and uncertainty are evidence to review, not proof of romantic chemistry."),tags$h4("Exposure relative to recorded eligibility"),tags$p(class="fine-print","Eligibility opportunities are measured when batches are generated, not continuously across the population. Served means a card was sent to a client, not that the member looked at it. This is an audit starting point, not a fairness guarantee."),tableOutput(ns("exposure"))),
      panel("Psychometric Validation Dashboard",tags$p("Item answers stay off this dashboard. Subscale reliability needs at least 30 consenting non-demo members. Reliability alone cannot justify retaining a tool. Predictive evidence needs later, held-out relationship outcomes."),tableOutput(ns("psych")),tags$p(class="fine-print","Use scripts/train_model.R for offline temporal evaluation and ablations. Evaluation artifacts are inactive until an operator explicitly approves a pilot. Revise/retire instruments through versioned configuration, with a recorded review and model invalidation.")),
      panel("Algorithm controls",selectInput(ns("algorithm"),"Registered algorithm",setNames(names(algorithms),vapply(algorithms,`[[`,"","label"))),checkboxInput(ns("enabled"),"Enable for new recommendation batches",TRUE),actionButton(ns("set_algorithm"),"Apply algorithm status",class="btn-outline-primary"),tags$p(class="fine-print","Changes are audited. Existing decisions are preserved. One algorithm must remain enabled. For an experiment, the operator creates a versioned assignment record; changing an algorithm during an experiment requires a new experiment ID.")),
      panel("Trust & safety",tags$p("Local operator review only; no staffed emergency or moderation service is implied."),tableOutput(ns("reports")),textInput(ns("target"),"Account ID from a report"),selectInput(ns("status"),"Account status",c("Active"="active","Suspended"="suspended")),textAreaInput(ns("reason"),"Review reason",rows=2),actionButton(ns("moderate"),"Record moderation decision",class="btn-outline-primary")))
  })
  output$models<-renderTable({req(user());revision();require_admin(con,user());rows<-DBI::dbGetQuery(con,"SELECT * FROM model_evaluation_results ORDER BY created_at DESC LIMIT 20");if(!nrow(rows))return(data.frame(Status="No offline evaluations recorded"));do.call(rbind,lapply(seq_len(nrow(rows)),function(i){x<-from_json(rows$result[i]);data.frame(Version=rows$model_version[i],Status=x$status%||%"evaluation_only",Target=x$target%||%"",Held_out_n=x$metrics$n%||%0,Brier=x$metrics$brier%||%NA_real_,AUROC=x$metrics$auc%||%NA_real_,ECE=x$metrics$ece%||%NA_real_)}))},striped=TRUE)
  output$metrics<-renderTable({report()$metrics},striped=TRUE)
  output$exposure<-renderTable({head(report()$exposure,30)},striped=TRUE)
  output$psych<-renderTable({report()$psychometrics},striped=TRUE)
  output$reports<-renderTable({req(user());revision();require_admin(con,user());DBI::dbGetQuery(con,"SELECT target_id,reason,created_at FROM reports ORDER BY created_at DESC LIMIT 30")},striped=TRUE)
  observeEvent(input$set_algorithm,tryCatch({admin_set_algorithm(con,user(),input$algorithm,isTRUE(input$enabled));on_saved();showNotification("Algorithm status recorded.",type="message")},error=function(e)showNotification(conditionMessage(e),type="error")))
  observeEvent(input$moderate,tryCatch({admin_moderate(con,user(),input$target,input$status,input$reason);on_saved();showNotification("Moderation decision recorded.",type="message")},error=function(e)showNotification(conditionMessage(e),type="error")))
})
